a(858,'<ffx:disgust>لكن كل هذا لا ينفع! <ffx:anger>لقد شوهد قطاع الطرق في القرية مجددًا! <ffx:wonder>وفوق ذلك، أمسك رفاقنا بجوّال اليوم!<ffx:neutral>')
